local MortarPestleStandMaker = {}
local PRODUCTS = {
    iron_mortarpestlestand = { name = "Železni stojalo za možnar", ironCost = 3, woodCost = 2, leatherCost = 1, time = 5, cost = 150, prestige = 4, happiness = 2, description = "Železni stojalo za možnar za kuhinjo." },
    bronze_mortarpestlestand = { name = "Bronast stojalo za možnar", bronzeCost = 3, ironCost = 1, woodCost = 2, leatherCost = 1, time = 7, cost = 365, prestige = 6, happiness = 3, description = "Bronast stojalo za možnar za kuhinjo." },
    silver_mortarpestlestand = { name = "Srebrn stojalo za možnar", silverCost = 3, bronzeCost = 1, ironCost = 1, woodCost = 2, leatherCost = 1, time = 11, cost = 880, prestige = 11, happiness = 4, description = "Srebrn stojalo za možnar za kuhinjo." },
    gilded_mortarpestlestand = { name = "Pozlačen stojalo za možnar", goldCost = 1, silverCost = 3, bronzeCost = 1, woodCost = 2, leatherCost = 1, time = 15, cost = 1900, prestige = 20, happiness = 5, description = "Pozlačen stojalo za možnar za kuhinjo." },
    jewel_set_mortarpestlestand = { name = "Draguljast stojalo za možnar", goldCost = 2, silverCost = 3, jewelCost = 1, bronzeCost = 1, woodCost = 2, leatherCost = 1, time = 19, cost = 4100, prestige = 36, happiness = 7, description = "Draguljast stojalo za možnar za kuhinjo." },
    royal_sovereign_mortarpestlestand = { name = "Kraljevski suveren stojalo za možnar", goldCost = 3, silverCost = 3, jewelCost = 2, pearlCost = 2, bronzeCost = 1, woodCost = 3, leatherCost = 1, time = 26, cost = 8800, prestige = 68, happiness = 13, description = "Suveren stojalo za možnar z biseri za krono." },
}
local BUILDINGS = {
    mortarpestlestand_workshop = { name = "Mortarpestlestand delavnica", cost = { gold = 325, wood = 185, stone = 130, iron = 7 }, upkeep = 6, qualityBonus = 5 },
    mortarpestlestand_house = { name = "Mortarpestlestand hiša", cost = { gold = 1185, wood = 370, stone = 265, silver = 7, iron = 7 }, upkeep = 25, qualityBonus = 18 },
    master_mortarpestlestand_atelier = { name = "Mojstrski mortarpestlestand atelje", cost = { gold = 2975, wood = 425, stone = 515, silver = 35, gold = 7 }, upkeep = 70, qualityBonus = 30 },
    sovereign_mortarpestlestand_palace = { name = "Suverena mortarpestlestand palača", cost = { gold = 12920, wood = 650, stone = 825, gold = 83, jewel = 19 }, upkeep = 253, qualityBonus = 55, prestigeBonus = 50 },
}
MortarPestleStandMaker.ironStock = 12; MortarPestleStandMaker.bronzeStock = 10; MortarPestleStandMaker.woodStock = 16; MortarPestleStandMaker.leatherStock = 10; MortarPestleStandMaker.silverStock = 8; MortarPestleStandMaker.goldStock = 6; MortarPestleStandMaker.jewelStock = 4; MortarPestleStandMaker.pearlStock = 4
MortarPestleStandMaker.productStock = {}; MortarPestleStandMaker.buildings = {}; MortarPestleStandMaker.maker = nil; MortarPestleStandMaker.activeMaking = {}; MortarPestleStandMaker.totalProducts = 0; MortarPestleStandMaker.dayTimer = 0
function MortarPestleStandMaker.init() MortarPestleStandMaker.ironStock=12; MortarPestleStandMaker.bronzeStock=10; MortarPestleStandMaker.woodStock=16; MortarPestleStandMaker.leatherStock=10; MortarPestleStandMaker.silverStock=8; MortarPestleStandMaker.goldStock=6; MortarPestleStandMaker.jewelStock=4; MortarPestleStandMaker.pearlStock=4; MortarPestleStandMaker.productStock={}; MortarPestleStandMaker.buildings={}; MortarPestleStandMaker.maker=nil; MortarPestleStandMaker.activeMaking={}; MortarPestleStandMaker.totalProducts=0; MortarPestleStandMaker.dayTimer=0; print("[MortarPestleStandMaker] Royal Mortar Pestle Stand Maker System initialized (6 products, 4 buildings)") end
function MortarPestleStandMaker.hireMaker(n,s) s=s or math.random(55,90); local c=570+s*12; if not _G.state or (_G.state.gold or 0)<c then return false,"Premalo zlata" end; _G.state.gold=_G.state.gold-c; MortarPestleStandMaker.maker={name=n or ("Stojalar "..math.random(1,99)),skill=s,hiredDay=os.time(),itemsMade=0}; if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Stojalar najet: %s (spretnost: %d)",MortarPestleStandMaker.maker.name,s),"success") end; return true end
function MortarPestleStandMaker.canBuild(id) local d=BUILDINGS[id]; if not d then return false,"Neznana zgradba" end; if not _G.state then return false,"Brez stanja" end; if _G.state.gold<(d.cost.gold or 0) then return false,"Premalo zlata" end; if _G.state.resources then for r,a in pairs(d.cost) do if r~="gold" and (_G.state.resources[r] or 0)<a then return false,"Premalo "..r end end end; return true end
function MortarPestleStandMaker.build(id) local ok,e=MortarPestleStandMaker.canBuild(id); if not ok then return false,e end; local d=BUILDINGS[id]; _G.state.gold=_G.state.gold-(d.cost.gold or 0); if _G.state.resources then for r,a in pairs(d.cost) do if r~="gold" then _G.state.resources[r]=(_G.state.resources[r] or 0)-a end end end; table.insert(MortarPestleStandMaker.buildings,{type=id,builtDay=os.time()}); if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,"Zgrajeno: "..d.name,"success") end; return true end
function MortarPestleStandMaker.getQualityBonus() local b=0; for _,bd in ipairs(MortarPestleStandMaker.buildings) do local d=BUILDINGS[bd.type]; if d and d.qualityBonus then b=b+d.qualityBonus end end; return b end
function MortarPestleStandMaker.canMake(pt) local d=PRODUCTS[pt]; if not d then return false,"Neznan produkt" end; if d.ironCost and MortarPestleStandMaker.ironStock<(d.ironCost or 0) then return false,"Premalo železa" end; if d.bronzeCost and MortarPestleStandMaker.bronzeStock<(d.bronzeCost or 0) then return false,"Premalo brona" end; if d.woodCost and MortarPestleStandMaker.woodStock<(d.woodCost or 0) then return false,"Premalo lesa" end; if d.leatherCost and MortarPestleStandMaker.leatherStock<(d.leatherCost or 0) then return false,"Premalo usnja" end; if d.silverCost and MortarPestleStandMaker.silverStock<(d.silverCost or 0) then return false,"Premalo srebra" end; if d.goldCost and MortarPestleStandMaker.goldStock<(d.goldCost or 0) then return false,"Premalo zlata" end; if d.jewelCost and MortarPestleStandMaker.jewelStock<(d.jewelCost or 0) then return false,"Premalo draguljev" end; if d.pearlCost and MortarPestleStandMaker.pearlStock<(d.pearlCost or 0) then return false,"Premalo biserov" end; if #MortarPestleStandMaker.buildings==0 then return false,"Potrebna stojalna delavnica" end; if not MortarPestleStandMaker.maker then return false,"Potreben stojalar" end; return true end
function MortarPestleStandMaker.make(pt,qty) qty=qty or 1; local ok,e=MortarPestleStandMaker.canMake(pt); if not ok then return false,e end; local d=PRODUCTS[pt]; if d.ironCost then MortarPestleStandMaker.ironStock=MortarPestleStandMaker.ironStock-d.ironCost*qty end; if d.bronzeCost then MortarPestleStandMaker.bronzeStock=MortarPestleStandMaker.bronzeStock-d.bronzeCost*qty end; if d.woodCost then MortarPestleStandMaker.woodStock=MortarPestleStandMaker.woodStock-d.woodCost*qty end; if d.leatherCost then MortarPestleStandMaker.leatherStock=MortarPestleStandMaker.leatherStock-d.leatherCost*qty end; if d.silverCost then MortarPestleStandMaker.silverStock=MortarPestleStandMaker.silverStock-d.silverCost*qty end; if d.goldCost then MortarPestleStandMaker.goldStock=MortarPestleStandMaker.goldStock-d.goldCost*qty end; if d.jewelCost then MortarPestleStandMaker.jewelStock=MortarPestleStandMaker.jewelStock-d.jewelCost*qty end; if d.pearlCost then MortarPestleStandMaker.pearlStock=MortarPestleStandMaker.pearlStock-d.pearlCost*qty end; local t=d.time; if MortarPestleStandMaker.maker then t=math.max(1,t-math.floor(MortarPestleStandMaker.maker.skill/13)) end; table.insert(MortarPestleStandMaker.activeMaking,{id="mortarpestlestand_"..tostring(os.time()).."_"..tostring(math.random(1000,9999)),productType=pt,productName=d.name,cost=d.cost*qty,quantity=qty,food=0,prestige=d.prestige or 0,happiness=d.happiness or 0,daysRemaining=t,started=os.time()}); if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Izdelava: %d %s (%d dni)",qty,d.name,t),"info") end; return true end
function MortarPestleStandMaker.completeMaking(m) local q=1.0+(MortarPestleStandMaker.getQualityBonus()/100); if MortarPestleStandMaker.maker then q=q+(MortarPestleStandMaker.maker.skill/140) end; q=math.min(2.5,q); MortarPestleStandMaker.productStock[m.productType]=(MortarPestleStandMaker.productStock[m.productType] or 0)+m.quantity; MortarPestleStandMaker.totalProducts=MortarPestleStandMaker.totalProducts+m.quantity; if m.prestige>0 and _G.state and _G.state.happiness then _G.state.happiness=math.min(100,_G.state.happiness+m.prestige) end; if m.happiness>0 and _G.state and _G.state.happiness then _G.state.happiness=math.min(100,_G.state.happiness+m.happiness) end; if MortarPestleStandMaker.maker then MortarPestleStandMaker.maker.itemsMade=MortarPestleStandMaker.maker.itemsMade+m.quantity; if math.random()<0.25 then MortarPestleStandMaker.maker.skill=math.min(100,MortarPestleStandMaker.maker.skill+1) end end; if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Stojalo izdelan: %d %s (kakovost: %.1f)",m.quantity,m.productName,q),"success") end; if _G.GameEventBus then pcall(_G.GameEventBus.publish,"mortarpestlestand.completed",{productName=m.productName,prestige=m.prestige,happiness=m.happiness}) end end
function MortarPestleStandMaker.update(dt) if not _G.state then return end; MortarPestleStandMaker.dayTimer=MortarPestleStandMaker.dayTimer+dt; if MortarPestleStandMaker.dayTimer>=30 then MortarPestleStandMaker.dayTimer=0; for i=#MortarPestleStandMaker.activeMaking,1,-1 do local m=MortarPestleStandMaker.activeMaking[i]; m.daysRemaining=m.daysRemaining-1; if m.daysRemaining<=0 then MortarPestleStandMaker.completeMaking(m); table.remove(MortarPestleStandMaker.activeMaking,i) end end; local tu=0; for _,bd in ipairs(MortarPestleStandMaker.buildings) do local d=BUILDINGS[bd.type]; if d and d.upkeep then tu=tu+d.upkeep end end; if MortarPestleStandMaker.maker then tu=tu+15 end; if tu>0 and _G.state then _G.state.gold=math.max(0,(_G.state.gold or 0)-tu) end end end
function MortarPestleStandMaker.getStats() return {ironStock=MortarPestleStandMaker.ironStock,bronzeStock=MortarPestleStandMaker.bronzeStock,woodStock=MortarPestleStandMaker.woodStock,leatherStock=MortarPestleStandMaker.leatherStock,silverStock=MortarPestleStandMaker.silverStock,goldStock=MortarPestleStandMaker.goldStock,jewelStock=MortarPestleStandMaker.jewelStock,pearlStock=MortarPestleStandMaker.pearlStock,productStock=MortarPestleStandMaker.productStock,numBuildings=#MortarPestleStandMaker.buildings,hasMaker=MortarPestleStandMaker.maker~=nil,makerName=MortarPestleStandMaker.maker and MortarPestleStandMaker.maker.name or "—",makerSkill=MortarPestleStandMaker.maker and MortarPestleStandMaker.maker.skill or 0,activeMaking=#MortarPestleStandMaker.activeMaking,totalProducts=MortarPestleStandMaker.totalProducts} end
return MortarPestleStandMaker
